def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def ref(p):return {'path':str(p),'sha256':sha(p),'bytes':p.stat().st_size}
def write(name,v):
    with (HERE/name).open('x',encoding='utf-8') as f:json.dump(v,f,ensure_ascii=False,indent=2);f.write('\n')
def command(label,args):
    started=datetime.datetime.now(datetime.timezone.utc).isoformat()
    p=subprocess.run(args,cwd=MAIN,capture_output=True)
    (HERE/(label+'.stdout.raw')).write_bytes(p.stdout);(HERE/(label+'.stderr.raw')).write_bytes(p.stderr)
    write(label+'.invocation.json',{'argv':args,'cwd':str(MAIN),'started':started,'finished':datetime.datetime.now(datetime.timezone.utc).isoformat(),'exit':p.returncode,'environment_override':{},'read_only':True,'stdout':ref(HERE/(label+'.stdout.raw')),'stderr':ref(HERE/(label+'.stderr.raw'))})
    return p.stdout.decode('utf-8',errors='strict').strip()
